import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import wasm from 'vite-plugin-wasm';

// The Midnight SDK ships WASM (onchain-runtime) that uses top-level await;
// Vite 8 (rolldown) with target 'esnext' supports that natively, so no extra
// plugin is needed. The compiled contract is copied into src/generated by
// scripts/sync-managed.mjs so it resolves against this package's node_modules.
export default defineConfig({
  // GitHub Pages serves from /<repo>/; Vercel/Netlify from /. Set VITE_BASE at build time.
  base: process.env.VITE_BASE ?? '/',
  cacheDir: './.vite',
  build: {
    target: 'esnext',
    minify: false,
    rollupOptions: {
      output: {
        manualChunks: (id) => {
          if (id.includes('onchain-runtime-v3')) return 'wasm';
        },
      },
    },
    commonjsOptions: {
      transformMixedEsModules: true,
      extensions: ['.js', '.cjs'],
      ignoreDynamicRequires: true,
    },
  },
  plugins: [
    react(),
    wasm(),
  ],
  optimizeDeps: {
    rolldownOptions: {
      platform: 'browser',
      moduleTypes: { '.wasm': 'binary' },
    },
    include: ['@midnight-ntwrk/compact-runtime'],
    exclude: [
      '@midnight-ntwrk/onchain-runtime-v3',
      '@midnight-ntwrk/onchain-runtime-v3/midnight_onchain_runtime_wasm_bg.wasm',
      '@midnight-ntwrk/onchain-runtime-v3/midnight_onchain_runtime_wasm.js',
    ],
  },
  resolve: {
    // The Midnight WASM runtime keeps class identities inside its module
    // instance: a StateValue built by one copy fails an `instanceof` check in
    // another with "expected instance of StateValue". compact-runtime accepts
    // ^3.0.0 while midnight-js-protocol pins 3.0.0 exactly, so npm is happy to
    // install two copies. package.json `overrides` pins the version; this
    // guarantees the bundler collapses it to a single module either way.
    dedupe: [
      '@midnight-ntwrk/onchain-runtime-v3',
      '@midnight-ntwrk/compact-runtime',
      '@midnight-ntwrk/ledger-v8',
    ],
    extensions: ['.mjs', '.js', '.ts', '.jsx', '.tsx', '.json', '.wasm'],
    mainFields: ['browser', 'module', 'main'],
  },
});
